// Extrai os dados da mensagem que chegou da Meta e padroniza o telefone.
const value = $input.first().json.body?.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0];
if (!msg) return [];

const legenda = (m) => (m?.caption ? ` Legenda: ${m.caption}` : '');
let texto = '';
switch (msg.type) {
  case 'text':        texto = msg.text?.body || ''; break;
  case 'button':      texto = msg.button?.text || ''; break;
  case 'interactive': texto = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || ''; break;
  case 'image':       texto = '[O cliente enviou uma imagem.]' + legenda(msg.image); break;
  case 'document':    texto = `[O cliente enviou um documento: ${msg.document?.filename || 'arquivo'}.]` + legenda(msg.document); break;
  case 'video':       texto = '[O cliente enviou um vídeo.]' + legenda(msg.video); break;
  case 'audio':       texto = '[O cliente enviou um áudio.]'; break;
  case 'sticker':     texto = '[O cliente enviou uma figurinha.]'; break;
  case 'location':    texto = `[O cliente enviou uma localização: ${msg.location?.name || ''} ${msg.location?.address || ''} (${msg.location?.latitude}, ${msg.location?.longitude})]`; break;
  case 'contacts':    texto = '[O cliente compartilhou um contato: ' + (msg.contacts || []).map(c => `${c.name?.formatted_name || ''} ${(c.phones || []).map(p => p.phone).join(' ')}`).join('; ') + ']'; break;
  case 'reaction':    return [];   // reações (👍 etc.) não geram resposta
  default:            texto = `[Mensagem do tipo ${msg.type}.]`;
}
texto = String(texto).replace(/\u0000/g, '').trim().slice(0, 4000);
if (!texto) return [];

// DDD + 8 últimos dígitos: bate com ou sem 55, 0, 9º dígito, espaços...
function chave(tel) {
  let d = String(tel || '').replace(/\D/g, '').replace(/^0+/, '');
  if (d.length >= 12 && d.startsWith('55')) d = d.slice(2).replace(/^0+/, '');
  if (d.length < 10 || d.length > 11) return null;
  return d.slice(0, 2) + d.slice(-8);
}
const esc = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");

const telefone = String(msg.from).replace(/\D/g, '');
const k = chave(telefone) || telefone.slice(-12);

return [{
  json: {
    wamid: msg.id,
    telefone,
    chave: k,
    tipo: msg.type,
    texto,
    nome_perfil: value.contacts?.[0]?.profile?.name || '',
    sql_wamid: esc(msg.id),
    sql_texto: esc(texto),
    sql_tipo: esc(msg.type),
  }
}];

