// Junta as mensagens que o cliente mandou em sequência num texto só.
// Se não veio nada, outra execução já cuidou (webhook duplicado): para aqui.
const textos = $input.all().map(i => i.json.texto).filter(t => t);
if (!textos.length) return [];
return [{ json: { mensagens_novas: textos.join('\n'), qtd: textos.length } }];

// Junta cadastro, estado do atendimento e histórico, e decide a rota.
const n = $('Normalizar').first().json;
const lote = $('Juntar_lote').first().json;
const cad = $('Carregar_cadastro').first().json || {};

const historico = $('Historico').all()
  .map(i => i.json)
  .filter(r => r && r.texto)
  .reverse()
  .map(r => (r.direcao === 'in' ? 'Cliente: ' : 'Orientar: ') + r.texto)
  .join('\n');

const tipoContato = cad.contato_tipo || (cad.contato_nome ? 'cliente' : 'novo');
const status = cad.status || '';

let rota = 'classificar';
if (tipoContato === 'interno' || tipoContato === 'ignorar') return [];  // equipe: robô não responde
if (tipoContato === 'orgao' || status === 'humano') rota = 'humano';
else if (status === 'coletando' && cad.categoria) rota = 'responder';

return [{
  json: {
    rota,
    telefone: n.telefone,
    chave: n.chave,
    nome_perfil: n.nome_perfil,
    contato_nome: cad.contato_nome || '',
    tipo_contato: tipoContato,
    atend_id: cad.atend_id || null,
    status,
    categoria: cad.categoria || '',
    historico: historico || '(sem mensagens anteriores)',
    mensagens_novas: lote.mensagens_novas,
  }
}];

// Limpa a resposta do classificador (espaços, acentos, pontuação) e define o status.
const raw = String($input.first().json.text || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const cats = ['ORCAMENTO', 'DOCUMENTOS', 'INFORMACOES', 'ENCERRAMENTO', 'SAUDACAO'];
const categoria = cats.find(c => raw.includes(c)) || 'SAUDACAO';
const status = categoria === 'ENCERRAMENTO' ? 'encerrado' : categoria === 'SAUDACAO' ? 'triagem' : 'coletando';
const ctx = $('Montar_contexto').first().json;
return [{ json: { categoria, status, atend_id_sql: ctx.atend_id ? String(Number(ctx.atend_id)) : 'NULL' } }];

